function supportsProperty(o,key){if(!o)return false;if(['font','size','color','bold','italic','underline','align','direction','spacing','lineHeight','autoFit'].includes(key))return isText(o);if(['background','textBg'].includes(key))return o.type==='text';if(key==='fill')return ['rect','ellipse','highlight','note'].includes(o.type);if(['stroke','strokeWidth'].includes(key))return ['rect','ellipse','line','arrow','pen','highlight'].includes(o.type);if(key==='noFill')return ['rect','ellipse','highlight'].includes(o.type);return true;}

function status(s){$('status').textContent=t(s);}
function titleCase(s){return s[0].toUpperCase()+s.slice(1);}
function initButtons(root=document){root.querySelectorAll('button[data-icon]').forEach(b=>{if(!b.querySelector('svg'))b.insertAdjacentHTML('afterbegin',icon(b.dataset.icon));});root.querySelectorAll('button').forEach(b=>{const key=b.dataset.tip||b.dataset.t||b.textContent.trim();b.title=t(key);b.setAttribute('aria-label',t(key));});}
function localize(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.querySelectorAll('[data-t]').forEach(el=>{const label=t(el.dataset.t);if(el.tagName==='BUTTON'){el.innerHTML=icon(el.dataset.icon)+`<span>${escape(label)}</span>`;}else el.textContent=label;});$('languageButton').innerHTML=icon('globe')+(lang==='en'?'العربية':'English');$('languageButton').title=lang==='en'?'Switch to Arabic':'التبديل إلى الإنجليزية';$('languageButton').setAttribute('aria-label',$('languageButton').title);initButtons();$('findInput').placeholder=t('Find text');$('replaceInput').placeholder=t('Replacement text');for(const id of ['findInput','replaceInput','pageJump','zoom','signaturePad']){const keys={findInput:'Find text',replaceInput:'Replacement text',pageJump:'Go to page',zoom:'Zoom',signaturePad:'Signature drawing pad'};$(id).setAttribute('aria-label',t(keys[id]));}setTool(tool);updateUI();}
function snapshot(){return JSON.stringify({pages,filename});}
function commit(label){const snap=snapshot();if(history[historyIndex]?.snapshot===snap)return;history=history.slice(0,historyIndex+1);history.push({label,snapshot:snap});historyIndex=history.length-1;queueDraft();updateUI();}
