function fontURL(family,bold=false){const folder={NotoSans:'NotoSans',NotoArabic:'NotoSansArabic',NotoNaskh:'NotoNaskhArabic'}[family]||'NotoSans';return `https://cdn.jsdelivr.net/gh/notofonts/noto-fonts@main/hinted/ttf/${folder}/${folder}-${bold?'Bold':'Regular'}.ttf`;}
