function textLines(o){const ctx=document.createElement('canvas').getContext('2d');let size=o.size;const setFont=()=>ctx.font=`${o.italic?'italic ':''}${o.bold?'700 ':''}${size}px ${o.font}`;setFont();const measure=s=>ctx.measureText(s).width+Math.max(0,[...s].length-1)*o.spacing;const max=Math.max(1,o.w-(o.type==='note'?20:0));const paragraphs=o.text.split('\n');if(o.autoFit){const widest=Math.max(1,...paragraphs.map(measure));size=Math.max(2,o.size*Math.min(1,max/widest));setFont();return {lines:paragraphs,measure,size};}const lines=[];for(const paragraph of paragraphs){if(!paragraph){lines.push('');continue;}let line='';for(const word of paragraph.split(/\s+/)){const next=line?line+' '+word:word;if(line&&measure(next)>max){lines.push(line);line=word;}else line=next;}lines.push(line);}return {lines,measure,size};}

