function encodeBase64(data){let text='';for(let i=0;i<data.length;i+=8192)text+=String.fromCharCode(...data.subarray(i,i+8192));return btoa(text);}
function decodeBase64(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0));}
function queueDraft(){if(!bytes)return;clearTimeout(saveTimer);$('draftStatus').textContent=t('Saving draft…');saveTimer=setTimeout(saveDraft,650);}
function saveDraft(){if(!bytes)return;try{const draft={version:2,bytes:encodeBase64(bytes),pages,initialPages,filename,history,historyIndex,savedAt:new Date().toISOString()};localStorage.setItem('paper-studio-draft',JSON.stringify(draft));$('draftStatus').textContent=`${t('Saved locally')} · ${historyIndex} ${lang==='ar'?'تعديلات':'changes'}`;}catch(e){$('draftStatus').textContent=t(e.name==='QuotaExceededError'?'Draft too large for browser storage. Export your PDF to keep it.':'Draft storage unavailable. Export your PDF to keep it.');}}
function showDraft(){try{const raw=localStorage.getItem('paper-studio-draft');if(raw){const d=JSON.parse(raw);if(d.version===2&&d.bytes&&d.pages?.length){$('restoreInfo').textContent=`${d.filename} · ${new Date(d.savedAt).toLocaleString(lang)}`;$('restoreDialog').showModal();}}}catch{status('Draft storage unavailable. Export your PDF to keep it.');}}
async function restoreDraft(){const d=JSON.parse(localStorage.getItem('paper-studio-draft'));$('restoreDialog').close();await work(()=>loadPDF(decodeBase64(d.bytes),d.filename,d));}
function signatureSetup(){const canvas=$('signaturePad');const paint=()=>{const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.strokeStyle='#172a42';ctx.lineWidth=3;ctx.lineCap='round';ctx.lineJoin='round';for(const stroke of signaturePoints){ctx.beginPath();stroke.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke();}};const point=e=>{const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height];};canvas.onpointerdown=e=>{signatureStroke=[point(e)];signaturePoints.push(signatureStroke);canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(signatureStroke){signatureStroke.push(point(e));paint();}};canvas.onpointerup=()=>signatureStroke=null;canvas.onpointercancel=()=>signatureStroke=null;return paint;}
const paintSignature=signatureSetup();
function insertSignature(){if(!signaturePoints.some(s=>s.length>1)){status('Draw a signature first');return;}const b=pointBounds(signaturePoints.flat());const canvas=document.createElement('canvas');canvas.width=Math.ceil(b.w+20);canvas.height=Math.ceil(b.h+20);canvas.getContext('2d').drawImage($('signaturePad'),b.x-10,b.y-10,b.w+20,b.h+20,0,0,b.w+20,b.h+20);pendingImage={url:canvas.toDataURL(),width:canvas.width,height:canvas.height};$('signatureDialog').close();setTool('image');status('Click or drag on a page to place it');}
async function uploadImage(file){if(!file)return;if(!['image/png','image/jpeg'].includes(file.type)||file.size>8*1024*1024){status('Please choose a PNG or JPEG under 8 MB');return;}const url=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const img=new Image();img.src=url;await img.decode();pendingImage={url,width:img.naturalWidth,height:img.naturalHeight};$('signatureDialog').close();setTool('image');status('Click or drag on a page to place it');}
function color(hex){const value=parseInt(hex.slice(1),16);return PDFLib.rgb(((value>>16)&255)/255,((value>>8)&255)/255,(value&255)/255);}
let mupdfModule=null;
async function exportPDF(){
 finishEditing();const P=PDFLib;const skeleton=await P.PDFDocument.create();const source=await P.PDFDocument.load(bytes);
 for(const model of pages){let page;if(model.src===null)page=skeleton.addPage([model.w,model.h]);else{[page]=await skeleton.copyPages(source,[model.src]);skeleton.addPage(page);}page.setRotation(P.degrees(0));}
 let base=await skeleton.save();
 if(pages.some(p=>p.objects.some(o=>(o.source&&(o.dirty||o.deleted))||(!o.deleted&&o.type==='whiteout')))){
  mupdfModule ||= import('https://cdn.jsdelivr.net/npm/mupdf@1.27.0/dist/mupdf.js');const M=await mupdfModule;const document=M.Document.openDocument(base,'application/pdf');
  try{for(let i=0;i<pages.length;i++){const page=document.loadPage(i);let count=0;for(const o of pages[i].objects){let box;if(o.source&&(o.dirty||o.deleted)){const r=o.source;box=[r.x,r.y+r.h*.26,r.x+r.w,r.y+r.h*.8];}else if(!o.deleted&&o.type==='whiteout'&&o.rotation===0){box=[o.x,o.y,o.x+o.w,o.y+o.h];}if(box){const annotation=page.createAnnotation('Redact');annotation.setRect(box);annotation.update();annotation.destroy();count++;}}if(count)page.applyRedactions(false,M.PDFPage.REDACT_IMAGE_NONE,M.PDFPage.REDACT_LINE_ART_NONE,M.PDFPage.REDACT_TEXT_REMOVE);page.destroy();}const buffer=document.saveToBuffer('garbage=4,compress');base=buffer.asUint8Array().slice();buffer.destroy();}finally{document.destroy();}
 }
 const doc=await P.PDFDocument.load(base);doc.registerFontkit(fontkit);const embedded=new Map(),images=new Map();
 const embedFont=async o=>{const key=o.font+o.bold;if(!embedded.has(key)){const f=await doc.embedFont(await getFontData(o.font,o.bold),{subset:true});embedded.set(key,f);}return embedded.get(key);};
 for(let pageIndex=0;pageIndex<pages.length;pageIndex++){const model=pages[pageIndex],page=doc.getPage(pageIndex);page.setRotation(P.degrees(model.rotation));
  const ox=model.originX||0,oy=model.originY||0;
  for(const o of model.objects){if(o.source&&(o.dirty||o.deleted))page.drawRectangle({x:ox+o.source.x,y:oy+model.h-o.source.y-o.source.h,width:o.source.w,height:o.source.h,color:P.rgb(1,1,1)});}
  for(const o of model.objects){if(o.deleted||(o.source&&!o.dirty))continue;const a=o.rotation*Math.PI/180;page.pushOperators(P.pushGraphicsState(),P.concatTransformationMatrix(Math.cos(a),-Math.sin(a),Math.sin(a),Math.cos(a),ox+o.x,oy+model.h-o.y));
   const options={opacity:o.opacity,borderOpacity:o.opacity};const sw=o.strokeWidth;
   if(isText(o)){
    if(o.type==='note'||o.background)page.drawRectangle({x:0,y:-o.h,width:o.w,height:o.h,color:color(o.type==='note'?o.fill:o.textBg),opacity:o.opacity});
    const font=await embedFont(o);const available=new Set(font.getCharacterSet());const {lines,measure,size}=textLines(o);const pad=o.type==='note'?10:0;
    for(let i=0;i<lines.length;i++){const text=lines[i];if(!text)continue;for(const char of text){if(!available.has(char.codePointAt(0)))throw Error(`Unsupported character “${char}” in ${o.font}. Choose another font or remove it.`);}
     const width=measure(text),x=o.align==='right'?o.w-pad-width:o.align==='center'?(o.w-width)/2:pad,y=-(pad+o.size*1.2+i*o.size*o.lineHeight);
     page.pushOperators(P.setCharacterSpacing(o.spacing));page.drawText(text,{x,y,font,size,color:color(o.color),opacity:o.opacity,ySkew:P.degrees(o.italic?12:0)});page.pushOperators(P.setCharacterSpacing(0));
     if(o.underline)page.drawLine({start:{x,y:y-o.size*.12},end:{x:x+width,y:y-o.size*.12},thickness:Math.max(.6,o.size*.05),color:color(o.color),opacity:o.opacity});
    }
   }else if(['rect','highlight','whiteout'].includes(o.type)){page.drawRectangle({x:sw/2,y:-o.h+sw/2,width:Math.max(0,o.w-sw),height:Math.max(0,o.h-sw),color:o.noFill?undefined:color(o.type==='whiteout'?'#ffffff':o.fill),borderColor:color(o.stroke),borderWidth:sw,...options});}
   else if(o.type==='ellipse'){page.drawEllipse({x:o.w/2,y:-o.h/2,xScale:Math.max(.1,(o.w-sw)/2),yScale:Math.max(.1,(o.h-sw)/2),color:o.noFill?undefined:color(o.fill),borderColor:color(o.stroke),borderWidth:sw,...options});}
   else if(['line','arrow','pen'].includes(o.type)){const points=o.points.length?o.points:[[0,0],[o.w,o.h]];for(let i=1;i<points.length;i++)page.drawLine({start:{x:points[i-1][0],y:-points[i-1][1]},end:{x:points[i][0],y:-points[i][1]},thickness:sw,color:color(o.stroke),opacity:o.opacity,lineCap:P.LineCapStyle.Round});if(o.type==='arrow'){const [a,b]=points,angle=Math.atan2(b[1]-a[1],b[0]-a[0]),len=Math.max(9,sw*4);for(const delta of [-.45,.45])page.drawLine({start:{x:b[0],y:-b[1]},end:{x:b[0]-len*Math.cos(angle+delta),y:-(b[1]-len*Math.sin(angle+delta))},thickness:sw,color:color(o.stroke),opacity:o.opacity});}}
   else if(o.type==='image'){if(!images.has(o.image))images.set(o.image,await (o.image.startsWith('data:image/jpeg')?doc.embedJpg(o.image):doc.embedPng(o.image)));page.drawImage(images.get(o.image),{x:0,y:-o.h,width:o.w,height:o.h,opacity:o.opacity});}
   page.pushOperators(P.popGraphicsState());
  }
 }
 doc.setTitle(filename.replace(/\.pdf$/i,''));doc.setProducer('Paper Studio • pdf-lib');return doc.save();
}
function download(data,name){const url=URL.createObjectURL(new Blob([data],{type:'application/pdf'}));urls.push(url);const a=document.createElement('a');a.href=url;a.download=name;a.click();return url;}
async function savePDF(){const name=$('exportName').value.trim();if(!name){status('Filename required');return;}$('exportDialog').close();await work(async()=>{const data=await exportPDF();download(data,name.endsWith('.pdf')?name:name+'.pdf');status('Exported PDF');saveDraft();},'Preparing PDF…');}
async function printPDF(){const win=window.open('about:blank','_blank');if(!win){status('Allow pop-ups to open the printable PDF.');return;}await work(async()=>{const data=await exportPDF();const url=URL.createObjectURL(new Blob([data],{type:'application/pdf'}));urls.push(url);win.location.href=url;status('PDF ready for printing');},'Preparing PDF…');}
function exportDialog(){if(!bytes)return;finishEditing();$('exportDialog').showModal();$('exportName').focus();}
const actions={
 open:()=>$('fileInput').click(),'export-dialog':exportDialog,save:savePDF,print:printPDF,theme:()=>{theme=theme==='light'?'dark':'light';document.documentElement.dataset.theme=theme;try{localStorage.setItem('paper-theme',theme);}catch{}},language:()=>{finishEditing();lang=lang==='en'?'ar':'en';try{localStorage.setItem('paper-language',lang);}catch{}localize();if(bytes)render();},shortcuts:()=>$('shortcutsDialog').showModal(),undo:()=>restoreHistory(historyIndex-1),redo:()=>restoreHistory(historyIndex+1),inspector:()=>$('inspector').classList.toggle('open'),image:()=>{if(bytes)$('imageInput').click();},signature:()=>{if(bytes)$('signatureDialog').showModal();},'signature-clear':()=>{signaturePoints=[];paintSignature();},'signature-upload':()=>$('imageInput').click(),'signature-insert':insertSignature,'close-dialog':()=>document.querySelectorAll('dialog[open]').forEach(d=>d.close()),'draft-discard':()=>{localStorage.removeItem('paper-studio-draft');$('restoreDialog').close();},'draft-restore':restoreDraft,
 find:()=>{$('findPanel').hidden=!$('findPanel').hidden;if(!$('findPanel').hidden)$('findInput').focus();},'find-close':()=>{$('findPanel').hidden=true;document.querySelectorAll('.found').forEach(el=>el.classList.remove('found'));},'find-next':findNext,'replace-all':replaceAll,deselect:()=>{finishEditing();selected.clear();renderSelection();},duplicate:duplicateSelection,delete:deleteSelection,lock:()=>mutate('Lock changed',()=>selection().forEach(o=>o.locked=!o.locked)),front:()=>mutate('Layer order changed',()=>pages.forEach(p=>{const picked=p.objects.filter(o=>selected.has(o.id)&&!o.locked);picked.forEach(o=>o.dirty=true);p.objects=p.objects.filter(o=>!picked.includes(o)).concat(picked);})),back:()=>mutate('Layer order changed',()=>pages.forEach(p=>{const picked=p.objects.filter(o=>selected.has(o.id)&&!o.locked);picked.forEach(o=>o.dirty=true);p.objects=picked.concat(p.objects.filter(o=>!picked.includes(o)));})),reset:()=>ask('Restore the original?','All current edits will be reset. You can undo this action.',()=>mutate('Original restored',()=>{pages=clone(initialPages);currentPage=0;selected.clear();})),
 'prev-page':()=>goPage(currentPage-1),'next-page':()=>goPage(currentPage+1),'zoom-in':()=>{finishEditing();zoom=Math.min(3,zoom+.15);render();},'zoom-out':()=>{finishEditing();zoom=Math.max(.2,zoom-.15);render();},'fit-width':()=>fit('width'),'fit-page':()=>fit('page'),continuous:()=>{finishEditing();continuous=!continuous;render();goPage(currentPage);}
};
document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>{if(busy)return;const a=b.dataset.action;if(a.startsWith('page-'))pageOperation(a);else actions[a]?.();}));
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));
$('fileInput').onchange=()=>{openFile($('fileInput').files[0]);$('fileInput').value='';};$('imageInput').onchange=()=>{uploadImage($('imageInput').files[0]).catch(e=>status(e.message));$('imageInput').value='';};
$('zoom').onchange=()=>{finishEditing();zoom=Number($('zoom').value);render();};$('pageJump').onchange=()=>goPage(Number($('pageJump').value)-1);
$('findInput').oninput=()=>{findIndex=-1;findText();};$('findInput').onkeydown=e=>{if(e.key==='Enter')findNext();};
document.querySelectorAll('[data-sample]').forEach(b=>b.onclick=()=>{const load=()=>work(async()=>{const r=await fetch('samples/'+b.dataset.sample);if(!r.ok)throw Error('Sample unavailable');await loadPDF(new Uint8Array(await r.arrayBuffer()),b.dataset.sample);});if(bytes&&historyIndex>0)ask('Open another document?','This replaces the current workspace. Export any changes you want to keep first.',load);else load();});
let dragDepth=0;document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault();});document.addEventListener('dragenter',e=>{if(e.dataTransfer.types.includes('Files')){dragDepth++;$('empty').classList.add('dragover');}});document.addEventListener('dragleave',()=>{if(--dragDepth<=0)$('empty').classList.remove('dragover');});document.addEventListener('drop',e=>{if(!e.dataTransfer.files.length)return;e.preventDefault();dragDepth=0;$('empty').classList.remove('dragover');openFile(e.dataTransfer.files[0]);});
document.addEventListener('keydown',e=>{const typing=e.target.matches('input,textarea,select,[contenteditable=true]');const cmd=e.metaKey||e.ctrlKey;const key=e.key.toLowerCase();if(cmd&&key==='s'){e.preventDefault();exportDialog();return;}if(cmd&&key==='f'&&!document.querySelector('dialog[open]')){e.preventDefault();$('findPanel').hidden=false;$('findInput').focus();return;}if(typing||busy||document.querySelector('dialog[open]'))return;if(cmd&&key==='z'){e.preventDefault();restoreHistory(historyIndex+(e.shiftKey?1:-1));}else if(cmd&&key==='y'){e.preventDefault();restoreHistory(historyIndex+1);}else if(cmd&&key==='d'){e.preventDefault();duplicateSelection();}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelection();}else if(e.key==='Escape'){selected.clear();setTool('select');renderSelection();}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)&&selected.size){e.preventDefault();mutate('Objects moved',()=>selection().filter(o=>!o.locked).forEach(o=>{const n=e.shiftKey?10:1;o.x+=(e.key==='ArrowRight'?n:e.key==='ArrowLeft'?-n:0);o.y+=(e.key==='ArrowDown'?n:e.key==='ArrowUp'?-n:0);o.dirty=true;}));}});
window.addEventListener('beforeunload',()=>{finishEditing();saveDraft();});
try{lang=localStorage.getItem('paper-language')||'en';theme=localStorage.getItem('paper-theme')||'light';}catch{}
document.documentElement.dataset.theme=theme;
if(!window.pdfjsLib||!window.PDFLib||!window.fontkit){status('A library could not load. Check your internet connection and reload.');}else{pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';localize();showDraft();}
